args<-commandArgs(TRUE);stopifnot(length(args)==2)
root<-args[1];sm<-args[2];d<-file.path(root,'inputs',sm);out<-file.path(root,'copykat',sm)
dir.create(out,recursive=TRUE,showWarnings=FALSE)
.libPaths(c('/mnt/BioDisk/wangmingyuan/osteosarcoma_CAF/phase3_identity_20260914/Rlib',.libPaths(),'/mnt/BioDisk/wangmingyuan/miniconda3/envs/R_4.5.2/lib/R/library'))
suppressPackageStartupMessages({library(Matrix);library(data.table);library(jsonlite);library(copykat)})
options(scipen=100);set.seed(270231)
tryCatch({
 c<-as.data.frame(fread(file.path(d,'cells.tsv')));g<-as.data.frame(fread(file.path(d,'genes.tsv')))
 x<-as(readMM(gzfile(file.path(d,'counts.mtx.gz'))),'CsparseMatrix');dimnames(x)<-list(g$feature_id,c$tool_id)
 stopifnot(ncol(x)==nrow(c),nrow(x)==nrow(g),!anyDuplicated(rownames(x)),!anyDuplicated(colnames(x)),all(colSums(x)==c$n_counts),all(x@x>=0),all(x@x==floor(x@x)))
 refs<-c$tool_id[c$reference_used];stopifnot(length(refs)>=30,sum(c$heldout_clean)>=20)
 anno<-get('full.anno',envir=as.environment('package:copykat'))
 amap<-anno[anno$hgnc_symbol %in% rownames(x),,drop=FALSE];amap<-amap[!duplicated(amap$hgnc_symbol),,drop=FALSE]
 ambiguous<-character(0)
 mat<-x[as.character(amap$hgnc_symbol),,drop=FALSE];stopifnot(nrow(mat)>5000)
 fwrite(amap,file.path(out,'gene_mapping.tsv'),sep='\t')
 params<-list(method='native_CopyKAT',package_version=as.character(packageVersion('copykat')),seed=270231,input_cells=ncol(x),input_genes=nrow(x),mapped_genes=nrow(mat),ambiguous_features_excluded=length(ambiguous),reference_cells=length(refs),clean_heldout_cells=sum(c$heldout_clean),ngene_chr=5,win_size=25,KS_cut=.1,LOW_DR=.05,UP_DR=.1,genome_argument='hg20',annotation='installed CopyKAT full.anno HGNC symbols; available source symbol features',threads=4,no_new_global_QC_filter=TRUE)
 write_json(params,file.path(out,'parameters.json'),pretty=TRUE,auto_unbox=TRUE)
 setwd(out)
 ck<-copykat::copykat(rawmat=as.matrix(mat),id.type='S',ngene.chr=5,win.size=25,KS.cut=.1,sam.name=sm,distance='euclidean',norm.cell.names=refs,output.seg=FALSE,plot.genes=FALSE,genome='hg20',n.cores=4,LOW.DR=.05,UP.DR=.1,cell.line='no')
 saveRDS(ck,file.path(out,'copykat_result.rds'))
 pred<-as.data.frame(ck$prediction);stopifnot(all(c('cell.names','copykat.pred') %in% names(pred)),!anyDuplicated(pred$cell.names))
 j<-match(c$tool_id,pred$cell.names);calls<-as.character(pred$copykat.pred[j]);calls[is.na(j)]<-'not_returned_by_software'
 fwrite(data.frame(cell_id=c$cell_id,tool_id=c$tool_id,native_copykat_call=calls),file.path(out,'cell_results.tsv'),sep='\t')
 sink(file.path(out,'sessionInfo.txt'));print(sessionInfo());sink()
 writeLines('AVAILABLE_INPUT_COPYKAT_COMPLETE',file.path(out,'COMPLETE'));cat('AVAILABLE_INPUT_COPYKAT_COMPLETE',sm,'\n')
},error=function(e){writeLines(conditionMessage(e),file.path(out,'FAILED'));cat('COPYKAT_FAILED',sm,conditionMessage(e),'\n');quit(status=1)})
